import sysconfig
import os

sysroot = os.environ.get("SYSROOT")
if sysroot:
    mips_inc = os.path.join(sysroot, "usr/include/python3.11")

    _orig_get_config_var = sysconfig.get_config_var
    def _custom_get_config_var(name):
        if name in ("INCLUDEPY", "CONFINCLUDEPY", "INCLDIR", "CONFINCLDIR"):
            return mips_inc
        return _orig_get_config_var(name)
    sysconfig.get_config_var = _custom_get_config_var

    _orig_get_path = sysconfig.get_path
    def _custom_get_path(name, scheme=None, vars=None, expand=True):
        if name in ("include", "platinclude"):
            return mips_inc
        return _orig_get_path(name, scheme, vars, expand)
    sysconfig.get_path = _custom_get_path
